  "quiz": [
    {
      "id": "q1",
      "q": "民国八年七月，戚春桃从义庄跑回家后一病不起。她在义庄撞见了什么？",
      "options": [
        {
          "key": "A",
          "text": "有人从棺里的尸身上取出私货"
        },
        {
          "key": "B",
          "text": "一具会跳的僵尸"
        },
        {
          "key": "C",
          "text": "有人偷棺材里的陪葬首饰"
        },
        {
          "key": "D",
          "text": "道长在后院炼丹"
        }
      ],
      "answer": "A",
      "clue": "md_df_4",
      "explain": "丹房暗格账簿靠前的一页记着：民国八年七月初九，戚家女撞见开棺取货，惊病昏死。"
    },
    {
      "id": "q2",
      "q": "戚春桃的旧棺材，为什么会停在义庄的寿材库里？",
      "options": [
        {
          "key": "A",
          "text": "戚家要把棺材迁回祖坟"
        },
        {
          "key": "B",
          "text": "后山坟地被大水冲开，旧棺收回义庄等着重葬"
        },
        {
          "key": "C",
          "text": "道长要开棺查看有无尸变"
        },
        {
          "key": "D",
          "text": "赶尸匠要把它运回湘西"
        }
      ],
      "answer": "B",
      "clue": "md_sc_2",
      "explain": "寿材库那口旧棺泡过水、糊着干泥，棺头黄纸写着后山、待重葬。"
    },
    {
      "id": "q3",
      "q": "赶尸匠撒纸钱这些年领进义庄的尸身里，缝着的是什么？",
      "options": [
        {
          "key": "A",
          "text": "金条"
        },
        {
          "key": "B",
          "text": "烟土"
        },
        {
          "key": "C",
          "text": "枪弹"
        },
        {
          "key": "D",
          "text": "银票"
        }
      ],
      "answer": "B",
      "clue": "md_niu_4",
      "explain": "大阿牛床脚地板下的油布包里是一团甜苦味的黑膏，裹着寿衣的蓝缎布条；丹房账簿也一棺一行记着几包货。"
    },
    {
      "id": "q4",
      "q": "吴问米向甄天罡借的那五十两，押的是什么？",
      "options": [
        {
          "key": "A",
          "text": "祖传的米升"
        },
        {
          "key": "B",
          "text": "儿子在香港的工钱"
        },
        {
          "key": "C",
          "text": "自家的房契"
        },
        {
          "key": "D",
          "text": "一块坟地"
        }
      ],
      "answer": "C",
      "clue": "md_wu_2",
      "explain": "吴问米抽屉里的借据抄本写明以自家房契作押，月息五分。"
    },
    {
      "id": "q5",
      "q": "何守正从哪一年起，每个月从甄天罡那里拿十两？",
      "options": [
        {
          "key": "A",
          "text": "民国五年"
        },
        {
          "key": "B",
          "text": "民国八年"
        },
        {
          "key": "C",
          "text": "民国十二年"
        },
        {
          "key": "D",
          "text": "民国十七年"
        }
      ],
      "answer": "B",
      "clue": "md_he_4",
      "explain": "何守正枕套里的小本子从民国八年秋天记起，每页一行「甄，十两」。"
    },
    {
      "id": "q6",
      "q": "民国八年八月，吴问米替戚家问米，最后对戚家说了什么？",
      "options": [
        {
          "key": "A",
          "text": "叫家里人去义庄讨个说法"
        },
        {
          "key": "B",
          "text": "春桃还困在棺材里"
        },
        {
          "key": "C",
          "text": "春桃想要一座纸扎大屋"
        },
        {
          "key": "D",
          "text": "春桃走得安详，不怪任何人"
        }
      ],
      "answer": "D",
      "clue": "md_wu_4",
      "explain": "吴问米的问米簿记着当年答的是走得安详，旁边另有一行她不敢说出口的小字。"
    }
  ],
